const config = {
  "previewFeatures": [],
  "clientVersion": "7.10.1",
  "engineVersion": "d1b3f377ca835d73fd50954a5e22128b9ebdd6b8",
  "activeProvider": "postgresql",
  "inlineSchema": "// ==============================================================================\n// DSL Stationery E-Commerce — Production Database Schema\n// Engine: PostgreSQL 18.4 (dsl_stationery)\n// ==============================================================================\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ------------------------------------------------------------------------------\n// ENUMS\n// ------------------------------------------------------------------------------\n\nenum UserRole {\n  CUSTOMER\n  STAFF\n  MANAGER\n  ADMIN\n}\n\nenum OrderStatus {\n  PENDING\n  CONFIRMED\n  PROCESSING\n  PACKED\n  SHIPPED\n  DELIVERED\n  CANCELLED\n}\n\nenum PaymentStatus {\n  PENDING\n  PAID\n  FAILED\n  PARTIALLY_REFUNDED\n  REFUNDED\n}\n\nenum PaymentMethod {\n  CASH_ON_DELIVERY\n  BANK_TRANSFER\n  CARD_PAYHERE\n  KOKO_BNPL\n}\n\nenum DiscountType {\n  PERCENTAGE\n  FIXED_AMOUNT\n  FREE_DELIVERY\n}\n\nenum PromotionType {\n  PERCENTAGE\n  FIXED_AMOUNT\n  FREE_DELIVERY\n  PRODUCT_SPECIFIC\n  CATEGORY_SPECIFIC\n  ORDER_LEVEL\n}\n\nenum PromotionStatus {\n  DRAFT\n  SCHEDULED\n  ACTIVE\n  EXPIRED\n  DISABLED\n}\n\nenum InventoryChangeReason {\n  RESTOCK\n  CORRECTION\n  DAMAGED\n  ORDER_FULFILLMENT\n  DEMO_RESET\n}\n\nenum BackInStockAlertStatus {\n  PENDING\n  PROCESSING\n  SENT\n  CANCELLED\n}\n\nenum ReservationStatus {\n  ACTIVE\n  CONSUMED\n  EXPIRED\n  RELEASED\n  PAYMENT_PENDING\n}\n\nenum PaymentAttemptStatus {\n  INITIATED\n  PROCESSING\n  SUCCEEDED\n  FAILED\n  EXPIRED\n}\n\nenum BankDepositStatus {\n  PENDING\n  VERIFIED\n  REJECTED\n}\n\nenum BannerStatus {\n  DRAFT\n  SCHEDULED\n  PUBLISHED\n  ARCHIVED\n}\n\n// ------------------------------------------------------------------------------\n// USERS & ADDRESSES\n// ------------------------------------------------------------------------------\n\nmodel User {\n  id           String   @id @default(cuid())\n  email        String   @unique\n  phone        String?\n  name         String\n  role         UserRole @default(CUSTOMER)\n  roleId       String?\n  assignedRole Role?    @relation(fields: [roleId], references: [id], onDelete: SetNull)\n  passwordHash String?\n  isActive     Boolean  @default(true)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  // Brute-force protection\n  failedLoginAttempts Int       @default(0)\n  lockedUntil         DateTime?\n\n  // Password reset (stores only a SHA-256 hash — never the raw token)\n  passwordResetTokenHash String?\n  passwordResetExpiresAt DateTime?\n\n  // Email verification (Phase B.1 — stores only a SHA-256 hash of OTP)\n  isEmailVerified             Boolean   @default(false)\n  emailVerificationOtpHash    String?\n  emailVerificationExpiresAt  DateTime?\n  emailVerificationAttempts   Int       @default(0)\n  emailVerificationLastSentAt DateTime?\n\n  addresses              Address[]\n  orders                 Order[]\n  wishlist               WishlistItem[]\n  savedLists             SavedList[]\n  savedStationeryLists   SavedStationeryList[]\n  auditLogs              AuditLog[]\n  refreshTokens          RefreshToken[]\n  cart                   Cart?\n  reservations           StockReservation[]\n  backInStockAlerts      BackInStockAlert[]\n  createdBanners         HomepageBanner[]        @relation(\"BannerCreatedBy\")\n  updatedBanners         HomepageBanner[]        @relation(\"BannerUpdatedBy\")\n  promotionRedemptions   PromotionRedemption[]\n  invitationsSent        AdminInvitation[]       @relation(\"InvitedAdmins\")\n  importPreviews         ProductImportPreview[]  @relation(\"ImportPreviewsCreated\")\n  importBatches          ProductImportBatch[]    @relation(\"ImportBatchesCreated\")\n  reviewedBankDeposits   BankDepositSubmission[] @relation(\"ReviewedBankDeposits\")\n  verificationChallenges VerificationChallenge[]\n  adminActivities        AdminActivityLog[]\n\n  @@index([email])\n  @@index([phone])\n  @@index([roleId])\n}\n\nmodel Address {\n  id           String   @id @default(cuid())\n  userId       String\n  user         User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  fullName     String\n  phone        String\n  email        String\n  addressLine1 String\n  addressLine2 String?\n  city         String\n  district     String // One of 25 Sri Lanka districts\n  postalCode   String?\n  isDefault    Boolean  @default(false)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  @@index([userId])\n  @@index([district])\n}\n\n// ------------------------------------------------------------------------------\n// REFRESH TOKENS (Authentication Sessions)\n// ------------------------------------------------------------------------------\n\nmodel RefreshToken {\n  id        String   @id @default(cuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  tokenHash String   @unique // SHA-256 of the raw refresh token — raw token is NEVER stored\n  isRevoked Boolean  @default(false)\n  expiresAt DateTime\n  createdAt DateTime @default(now())\n  // Note: @unique on tokenHash already creates a B-tree unique index.\n  // A redundant @@index([tokenHash]) is intentionally omitted.\n\n  @@index([userId])\n  @@index([expiresAt])\n}\n\n// ------------------------------------------------------------------------------\n// CATALOG (CATEGORIES, BRANDS, PRODUCTS & VARIANTS)\n// ------------------------------------------------------------------------------\n\nmodel Category {\n  id           String     @id @default(cuid())\n  name         String\n  slug         String     @unique\n  description  String\n  iconName     String?\n  image        String?\n  featured     Boolean    @default(false)\n  displayOrder Int        @default(0)\n  parentId     String?\n  parent       Category?  @relation(\"CategoryHierarchy\", fields: [parentId], references: [id], onDelete: Restrict)\n  children     Category[] @relation(\"CategoryHierarchy\")\n  createdAt    DateTime   @default(now())\n  updatedAt    DateTime   @updatedAt\n\n  products    Product[]           @relation(\"ProductCategory\")\n  subProducts Product[]           @relation(\"ProductSubcategory\")\n  promotions  PromotionCategory[]\n\n  @@index([slug])\n  @@index([featured])\n  @@index([parentId])\n}\n\nmodel Brand {\n  id            String   @id @default(cuid())\n  name          String\n  slug          String   @unique\n  description   String\n  logo          String?\n  originCountry String\n  featured      Boolean  @default(false)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  products Product[]\n\n  @@index([slug])\n}\n\nmodel Product {\n  id                  String    @id @default(cuid())\n  name                String\n  slug                String    @unique\n  sku                 String    @unique\n  barcode             String?   @unique\n  description         String\n  shortDescription    String\n  categoryId          String\n  category            Category  @relation(\"ProductCategory\", fields: [categoryId], references: [id], onDelete: Restrict)\n  subcategoryId       String?\n  subcategory         Category? @relation(\"ProductSubcategory\", fields: [subcategoryId], references: [id], onDelete: Restrict)\n  brandId             String\n  brand               Brand     @relation(fields: [brandId], references: [id], onDelete: Restrict)\n  priceCents          Int // Price in integer cents (e.g. 45000 = Rs. 450.00)\n  compareAtPriceCents Int?\n  costPriceCents      Int?\n  stockQuantity       Int       @default(0)\n  lowStockThreshold   Int       @default(5)\n  isActive            Boolean   @default(true)\n  isFeatured          Boolean   @default(false)\n  isNewArrival        Boolean   @default(false)\n  isBestSeller        Boolean   @default(false)\n  images              String[]  @default([])\n  tags                String[]  @default([]) // Keywords including Sinhala/Tamil\n  rating              Float     @default(5.0)\n  reviewCount         Int       @default(0)\n  specifications      Json      @default(\"{}\")\n  createdAt           DateTime  @default(now())\n  updatedAt           DateTime  @updatedAt\n\n  variants          ProductVariant[]\n  globalSku         GlobalSku?\n  movements         InventoryMovement[]\n  orderItems        OrderItem[]\n  packItems         SchoolPackItem[]\n  wishlistItems     WishlistItem[]\n  savedListItems    SavedListItem[]\n  cartItems         CartItem[]\n  reservationItems  StockReservationItem[]\n  backInStockAlerts BackInStockAlert[]\n  promotions        PromotionProduct[]\n\n  @@index([slug])\n  @@index([sku])\n  @@index([categoryId])\n  @@index([subcategoryId])\n  @@index([brandId])\n  @@index([isActive])\n  @@index([priceCents])\n}\n\nmodel ProductVariant {\n  id                  String   @id @default(cuid())\n  productId           String\n  product             Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n  name                String // e.g. \"Blue Ink / Single Line\"\n  sku                 String   @unique\n  priceCents          Int\n  compareAtPriceCents Int?\n  stockQuantity       Int      @default(0)\n  attributes          Json // { \"color\": \"Blue\", \"ruling\": \"Single Line\" }\n  isActive            Boolean  @default(true)\n  createdAt           DateTime @default(now())\n  updatedAt           DateTime @updatedAt\n\n  orderItems       OrderItem[]\n  globalSku        GlobalSku?\n  movements        InventoryMovement[]\n  cartItems        CartItem[]\n  reservationItems StockReservationItem[]\n\n  @@index([productId])\n  @@index([sku])\n}\n\nmodel InventoryMovement {\n  id               String                @id @default(cuid())\n  productId        String\n  product          Product               @relation(fields: [productId], references: [id], onDelete: Cascade)\n  variantId        String?\n  variant          ProductVariant?       @relation(fields: [variantId], references: [id], onDelete: SetNull)\n  previousQuantity Int\n  newQuantity      Int\n  changeAmount     Int\n  reason           InventoryChangeReason\n  note             String?\n  performedById    String?\n  createdAt        DateTime              @default(now())\n\n  @@index([productId])\n  @@index([createdAt])\n}\n\n// ------------------------------------------------------------------------------\n// SCHOOL PACKS & BUNDLES\n// ------------------------------------------------------------------------------\n\nmodel SchoolPack {\n  id                String   @id @default(cuid())\n  name              String\n  slug              String   @unique\n  grade             String // e.g. \"Grade 1-2\", \"Grade 6-9\", \"O/L\"\n  tier              String // \"essential\", \"standard\", \"premium\"\n  description       String\n  savingsPercentage Int      @default(10)\n  totalPriceCents   Int\n  isActive          Boolean  @default(true)\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  items SchoolPackItem[]\n\n  @@index([slug])\n  @@index([grade])\n}\n\nmodel SchoolPackItem {\n  id                   String     @id @default(cuid())\n  packId               String\n  pack                 SchoolPack @relation(fields: [packId], references: [id], onDelete: Cascade)\n  productId            String\n  product              Product    @relation(fields: [productId], references: [id], onDelete: Restrict)\n  defaultQuantity      Int        @default(1)\n  unitPriceCents       Int\n  substituteProductIds String[]   @default([])\n  createdAt            DateTime   @default(now())\n\n  @@index([packId])\n  @@index([productId])\n}\n\n// ------------------------------------------------------------------------------\n// ORDERS & IMMUTABLE SNAPSHOTS\n// ------------------------------------------------------------------------------\n\nmodel Order {\n  id                    String                @id @default(cuid())\n  orderNumber           String                @unique // e.g. \"DSL-2026-4891\"\n  userId                String?\n  user                  User?                 @relation(fields: [userId], references: [id], onDelete: SetNull)\n  customerName          String\n  customerEmail         String\n  customerPhone         String\n  subtotalCents         Int\n  discountCents         Int                   @default(0)\n  deliveryCents         Int                   @default(0)\n  totalCents            Int\n  paymentMethod         PaymentMethod\n  paymentStatus         PaymentStatus         @default(PENDING)\n  orderStatus           OrderStatus           @default(PENDING)\n  notes                 String?\n  trackingNumber        String?\n  estimatedDeliveryDate DateTime?\n  promotionId           String?\n  promotion             Promotion?            @relation(fields: [promotionId], references: [id], onDelete: SetNull)\n  promoCode             String?\n  promotionRedemptions  PromotionRedemption[]\n  createdAt             DateTime              @default(now())\n  updatedAt             DateTime              @updatedAt\n\n  addressSnapshot        OrderAddressSnapshot?\n  items                  OrderItem[]\n  reservation            StockReservation?\n  paymentAttempts        PaymentAttempt[]\n  auditLogs              OrderAuditLog[]\n  orderNotes             OrderNote[]\n  returnRequests         OrderReturnRequest[]\n  refundRecords          RefundRecord[]\n  bankDepositSubmissions BankDepositSubmission[]\n\n  // Guest order tracking security (Phase B.1 — stores only a SHA-256 hash of OTP)\n  trackingOtpHash       String?\n  trackingOtpExpiresAt  DateTime?\n  trackingOtpAttempts   Int       @default(0)\n  trackingOtpLastSentAt DateTime?\n\n  @@index([orderNumber])\n  @@index([customerEmail])\n  @@index([customerPhone])\n  @@index([orderStatus])\n  @@index([createdAt])\n}\n\nmodel OrderAddressSnapshot {\n  id               String  @id @default(cuid())\n  orderId          String  @unique\n  order            Order   @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  fullName         String\n  phone            String\n  email            String\n  addressLine1     String\n  addressLine2     String?\n  city             String\n  district         String // One of 25 Sri Lanka districts\n  postalCode       String?\n  province         String?\n  buildingNo       String?\n  street           String?\n  landmark         String?\n  formattedAddress String?\n  latitude         Float?\n  longitude        Float?\n  deliveryNotes    String?\n}\n\nmodel OrderItem {\n  id              String            @id @default(cuid())\n  orderId         String\n  order           Order             @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  productId       String\n  product         Product           @relation(fields: [productId], references: [id], onDelete: Restrict)\n  variantId       String?\n  variant         ProductVariant?   @relation(fields: [variantId], references: [id], onDelete: SetNull)\n  productName     String // Frozen name snapshot\n  variantName     String? // Frozen variant name snapshot\n  sku             String // Frozen SKU snapshot\n  unitPriceCents  Int // Frozen price snapshot at purchase time\n  quantity        Int\n  totalPriceCents Int // unitPriceCents * quantity\n  createdAt       DateTime          @default(now())\n  returnItems     OrderReturnItem[]\n\n  @@index([orderId])\n  @@index([productId])\n}\n\n// ------------------------------------------------------------------------------\n// ORDER MANAGEMENT: AUDIT, NOTES, RETURNS & REFUNDS\n// ------------------------------------------------------------------------------\n\nenum ReturnStatus {\n  PENDING\n  APPROVED\n  REJECTED\n  COMPLETED\n}\n\nenum ReturnItemStatus {\n  PENDING\n  APPROVED\n  REJECTED\n  RECEIVED\n  REFUNDED\n}\n\nenum RefundStatus {\n  REQUESTED\n  APPROVED\n  PROCESSING\n  COMPLETED\n  FAILED\n  REJECTED\n}\n\nmodel OrderAuditLog {\n  id            String   @id @default(cuid())\n  orderId       String\n  order         Order    @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  adminId       String?\n  adminName     String   @default(\"System\")\n  action        String // \"STATUS_CHANGE\", \"CUSTOMER_UPDATE\", \"DELIVERY_UPDATE\", \"ITEMS_UPDATE\", \"ORDER_CANCELLED\", \"RETURN_DECISION\", \"REFUND_RECORDED\", \"NOTE_ADDED\"\n  fieldChanged  String?\n  previousValue String?\n  newValue      String?\n  reason        String?\n  createdAt     DateTime @default(now())\n\n  @@index([orderId])\n  @@index([createdAt])\n}\n\nmodel OrderNote {\n  id         String   @id @default(cuid())\n  orderId    String\n  order      Order    @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  authorId   String?\n  authorName String   @default(\"Staff\")\n  note       String\n  isInternal Boolean  @default(true)\n  createdAt  DateTime @default(now())\n\n  @@index([orderId])\n}\n\nmodel OrderReturnRequest {\n  id              String            @id @default(cuid())\n  orderId         String\n  order           Order             @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  returnNumber    String            @unique\n  status          ReturnStatus      @default(PENDING)\n  reason          String\n  rejectionReason String?\n  items           OrderReturnItem[]\n  refundRecords   RefundRecord[]\n  createdAt       DateTime          @default(now())\n  updatedAt       DateTime          @updatedAt\n\n  @@index([orderId])\n}\n\nmodel OrderReturnItem {\n  id              String             @id @default(cuid())\n  returnRequestId String\n  returnRequest   OrderReturnRequest @relation(fields: [returnRequestId], references: [id], onDelete: Cascade)\n  orderItemId     String\n  orderItem       OrderItem          @relation(fields: [orderItemId], references: [id], onDelete: Cascade)\n  productName     String\n  quantity        Int\n  reason          String\n  status          ReturnItemStatus   @default(PENDING)\n  rejectionReason String?\n  receivedAt      DateTime?\n  createdAt       DateTime           @default(now())\n\n  @@index([returnRequestId])\n  @@index([orderItemId])\n}\n\nmodel RefundRecord {\n  id                   String              @id @default(cuid())\n  orderId              String\n  order                Order               @relation(fields: [orderId], references: [id], onDelete: Restrict)\n  amountCents          Int\n  currency             String              @default(\"LKR\")\n  method               String // e.g. \"BANK_TRANSFER\", \"CARD_PAYHERE\", \"KOKO_BNPL\", \"CASH\", \"STORE_CREDIT\"\n  status               RefundStatus        @default(REQUESTED)\n  reference            String?\n  externalReference    String?\n  idempotencyKey       String?\n  payloadHash          String?\n  reason               String\n  failureReason        String?\n  maskedAccountNumber  String?\n  encryptedBankDetails String?\n  processedBy          String?\n  processedById        String?\n  requestedById        String? // Explicit ID of admin who requested refund/cancellation\n  approvedById         String?\n  approvedAt           DateTime?\n  completedById        String? // Explicit ID of independent admin who verified execution and completed refund\n  completedAt          DateTime?\n  orderReturnRequestId String?\n  orderReturnRequest   OrderReturnRequest? @relation(fields: [orderReturnRequestId], references: [id], onDelete: Restrict)\n  metadata             Json?\n  createdAt            DateTime            @default(now())\n  updatedAt            DateTime            @updatedAt\n\n  @@unique([orderId, idempotencyKey])\n  @@index([orderId])\n  @@index([status])\n  @@index([orderReturnRequestId])\n}\n\n// ------------------------------------------------------------------------------\n// STOCK RESERVATIONS & PAYMENT ATTEMPTS\n// ------------------------------------------------------------------------------\n\nmodel StockReservation {\n  id             String            @id @default(cuid())\n  userId         String?\n  user           User?             @relation(fields: [userId], references: [id], onDelete: SetNull)\n  sessionId      String? // Anonymous guest checkout session\n  status         ReservationStatus @default(ACTIVE)\n  expiresAt      DateTime\n  idempotencyKey String?           @unique\n  orderId        String?           @unique\n  order          Order?            @relation(fields: [orderId], references: [id], onDelete: SetNull)\n  createdAt      DateTime          @default(now())\n  updatedAt      DateTime          @updatedAt\n\n  items           StockReservationItem[]\n  paymentAttempts PaymentAttempt[]\n\n  @@index([userId])\n  @@index([sessionId])\n  @@index([status])\n  @@index([expiresAt])\n}\n\nmodel StockReservationItem {\n  id             String           @id @default(cuid())\n  reservationId  String\n  reservation    StockReservation @relation(fields: [reservationId], references: [id], onDelete: Cascade)\n  productId      String\n  product        Product          @relation(fields: [productId], references: [id], onDelete: Restrict)\n  variantId      String?\n  variant        ProductVariant?  @relation(fields: [variantId], references: [id], onDelete: SetNull)\n  quantity       Int\n  unitPriceCents Int\n  createdAt      DateTime         @default(now())\n\n  @@index([reservationId])\n  @@index([productId])\n  @@index([variantId])\n}\n\nmodel PaymentAttempt {\n  id               String               @id @default(cuid())\n  reservationId    String\n  reservation      StockReservation     @relation(fields: [reservationId], references: [id], onDelete: Cascade)\n  orderId          String?\n  order            Order?               @relation(fields: [orderId], references: [id], onDelete: SetNull)\n  amountCents      Int\n  currency         String               @default(\"LKR\")\n  paymentMethod    PaymentMethod\n  status           PaymentAttemptStatus @default(INITIATED)\n  gatewayReference String?              @unique\n  idempotencyKey   String?              @unique\n  gatewayPayload   Json?\n  failureReason    String?\n  createdAt        DateTime             @default(now())\n  updatedAt        DateTime             @updatedAt\n\n  bankDepositSubmissions BankDepositSubmission[]\n\n  @@index([reservationId])\n  @@index([orderId])\n  @@index([status])\n}\n\n// ------------------------------------------------------------------------------\n// BANK DEPOSIT SUBMISSIONS (Stage 3.2)\n// ------------------------------------------------------------------------------\n\nmodel BankDepositSubmission {\n  id               String          @id @default(cuid())\n  orderId          String\n  order            Order           @relation(fields: [orderId], references: [id], onDelete: Restrict)\n  paymentAttemptId String?\n  paymentAttempt   PaymentAttempt? @relation(fields: [paymentAttemptId], references: [id], onDelete: SetNull)\n\n  // Storage & file metadata\n  receiptStorageKey String\n  originalFilename  String\n  fileSizeBytes     Int\n  mimeType          String\n  fileHashSha256    String?\n\n  // Customer claimed deposit data\n  referenceNumber String\n  depositDate     DateTime\n  amountCents     Int\n  customerNotes   String?\n\n  // Verification Lifecycle\n  status          BankDepositStatus @default(PENDING)\n  rejectionReason String?\n  reviewedById    String?\n  reviewedBy      User?             @relation(\"ReviewedBankDeposits\", fields: [reviewedById], references: [id], onDelete: SetNull)\n  reviewedAt      DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([orderId])\n  @@index([status])\n  @@index([referenceNumber])\n  @@index([paymentAttemptId])\n}\n\n// ------------------------------------------------------------------------------\n// PROMOTIONS & VOUCHERS\n// ------------------------------------------------------------------------------\n\nmodel Promotion {\n  id                         String          @id @default(cuid())\n  name                       String          @default(\"\")\n  title                      String?\n  code                       String?         @unique\n  description                String?\n  promotionType              PromotionType   @default(PERCENTAGE)\n  discountType               DiscountType    @default(PERCENTAGE)\n  discountValue              Int // Percentage (e.g. 10) or Fixed Rupees/Cents\n  maximumDiscountAmount      Int? // Maximum cap in cents\n  maxDiscountCents           Int? // Legacy alias in cents\n  minimumOrderAmount         Int? // Minimum order in cents\n  minOrderAmountCents        Int? // Legacy alias in cents\n  status                     PromotionStatus @default(ACTIVE)\n  startDate                  DateTime\n  endDate                    DateTime\n  priority                   Int             @default(0)\n  isStackableWithSchoolPacks Boolean         @default(false)\n  isActive                   Boolean         @default(true)\n  usageLimit                 Int?\n  usageCount                 Int             @default(0)\n  createdBy                  String?\n  updatedBy                  String?\n  createdAt                  DateTime        @default(now())\n  updatedAt                  DateTime        @updatedAt\n\n  codes              PromotionCode[]\n  eligibleProducts   PromotionProduct[]\n  eligibleCategories PromotionCategory[]\n  redemptions        PromotionRedemption[]\n  orders             Order[]\n\n  @@index([code])\n  @@index([isActive])\n  @@index([status])\n  @@index([startDate, endDate])\n}\n\nmodel PromotionCode {\n  id                      String    @id @default(cuid())\n  promotionId             String\n  promotion               Promotion @relation(fields: [promotionId], references: [id], onDelete: Cascade)\n  code                    String    @unique\n  isActive                Boolean   @default(true)\n  maximumTotalUsage       Int?\n  maximumUsagePerCustomer Int?\n  totalUsage              Int       @default(0)\n  createdAt               DateTime  @default(now())\n  updatedAt               DateTime  @updatedAt\n\n  redemptions PromotionRedemption[]\n\n  @@index([promotionId])\n  @@index([code])\n}\n\nmodel PromotionProduct {\n  id          String    @id @default(cuid())\n  promotionId String\n  promotion   Promotion @relation(fields: [promotionId], references: [id], onDelete: Cascade)\n  productId   String\n  product     Product   @relation(fields: [productId], references: [id], onDelete: Cascade)\n  createdAt   DateTime  @default(now())\n\n  @@unique([promotionId, productId])\n  @@index([promotionId])\n  @@index([productId])\n}\n\nmodel PromotionCategory {\n  id          String    @id @default(cuid())\n  promotionId String\n  promotion   Promotion @relation(fields: [promotionId], references: [id], onDelete: Cascade)\n  categoryId  String\n  category    Category  @relation(fields: [categoryId], references: [id], onDelete: Cascade)\n  createdAt   DateTime  @default(now())\n\n  @@unique([promotionId, categoryId])\n  @@index([promotionId])\n  @@index([categoryId])\n}\n\nmodel PromotionRedemption {\n  id              String         @id @default(cuid())\n  promotionId     String\n  promotion       Promotion      @relation(fields: [promotionId], references: [id], onDelete: Cascade)\n  promotionCodeId String?\n  promotionCode   PromotionCode? @relation(fields: [promotionCodeId], references: [id], onDelete: SetNull)\n  customerId      String?\n  customer        User?          @relation(fields: [customerId], references: [id], onDelete: SetNull)\n  customerEmail   String?\n  orderId         String?\n  order           Order?         @relation(fields: [orderId], references: [id], onDelete: SetNull)\n  discountAmount  Int // in cents\n  redeemedAt      DateTime       @default(now())\n\n  @@unique([orderId, promotionId])\n  @@index([promotionId])\n  @@index([promotionCodeId])\n  @@index([customerId])\n  @@index([customerEmail])\n  @@index([orderId])\n}\n\n// ------------------------------------------------------------------------------\n// WISHLIST & SAVED LISTS\n// ------------------------------------------------------------------------------\n\nmodel WishlistItem {\n  id        String   @id @default(cuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  productId String\n  product   Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n  createdAt DateTime @default(now())\n\n  @@unique([userId, productId])\n  @@index([userId])\n}\n\nmodel SavedStationeryList {\n  id             String   @id @default(cuid())\n  userId         String\n  user           User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  title          String\n  description    String?\n  itemProductIds String[] @default([])\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  @@index([userId])\n}\n\nmodel SavedList {\n  id        String          @id @default(cuid())\n  userId    String\n  user      User            @relation(fields: [userId], references: [id], onDelete: Cascade)\n  name      String\n  items     SavedListItem[]\n  createdAt DateTime        @default(now())\n  updatedAt DateTime        @updatedAt\n\n  @@index([userId])\n}\n\nmodel SavedListItem {\n  id          String    @id @default(cuid())\n  savedListId String\n  savedList   SavedList @relation(fields: [savedListId], references: [id], onDelete: Cascade)\n  productId   String\n  product     Product   @relation(fields: [productId], references: [id], onDelete: Cascade)\n  quantity    Int       @default(1)\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  @@unique([savedListId, productId])\n  @@index([savedListId])\n  @@index([productId])\n}\n\n// ------------------------------------------------------------------------------\n// AUDIT LOGS, BANNERS & STORE SETTINGS\n// ------------------------------------------------------------------------------\n\nmodel StoreBanner {\n  id              String   @id @default(cuid())\n  title           String\n  subtitle        String\n  ctaText         String\n  ctaLink         String\n  badgeText       String?\n  backgroundColor String   @default(\"#0066CC\")\n  textColor       String   @default(\"#FFFFFF\")\n  imageUrl        String?\n  isActive        Boolean  @default(true)\n  displayOrder    Int      @default(0)\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  @@index([isActive])\n}\n\nmodel HomepageBanner {\n  id           String       @id @default(cuid())\n  title        String\n  subtitle     String?\n  description  String?\n  desktopImage String\n  mobileImage  String?\n  imageAltText String\n  buttonText   String?\n  buttonLink   String?\n  placement    String?      @default(\"HERO\")\n  sortOrder    Int          @default(0)\n  status       BannerStatus @default(DRAFT)\n  startAt      DateTime?\n  endAt        DateTime?\n  createdById  String?\n  updatedById  String?\n  createdBy    User?        @relation(\"BannerCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  updatedBy    User?        @relation(\"BannerUpdatedBy\", fields: [updatedById], references: [id], onDelete: SetNull)\n  createdAt    DateTime     @default(now())\n  updatedAt    DateTime     @updatedAt\n\n  @@index([status, sortOrder])\n  @@index([startAt, endAt])\n}\n\nmodel AuditLog {\n  id          String   @id @default(cuid())\n  action      String // e.g. \"INVENTORY_ADJUST\", \"ORDER_STATUS_UPDATE\"\n  entityType  String // \"product\", \"order\", \"promotion\", \"inventory\"\n  entityId    String\n  description String\n  userId      String?\n  user        User?    @relation(fields: [userId], references: [id], onDelete: SetNull)\n  createdAt   DateTime @default(now())\n\n  @@index([entityType, entityId])\n  @@index([createdAt])\n}\n\nmodel StoreSettings {\n  id                         String  @id @default(\"default\")\n  flatDeliveryFeeCents       Int     @default(35000) // Rs. 350.00\n  freeDeliveryThresholdCents Int     @default(500000) // Rs. 5,000.00\n  hotlinePhone               String  @default(\"+94 11 200 9000\")\n  whatsappNumber             String  @default(\"+94 77 123 4567\")\n  contactEmail               String  @default(\"support@dslstationery.lk\")\n  codEnabled                 Boolean @default(true)\n  bankTransferEnabled        Boolean @default(false)\n  onlineCardEnabled          Boolean @default(false)\n\n  // Bank Transfer Configuration (Stage 3.1) - All default to NULL\n  bankName              String?\n  accountHolderName     String?\n  accountNumber         String?\n  branchName            String?\n  branchCode            String?\n  bankCode              String?\n  paymentInstructions   String?\n  referenceInstructions String?\n  bankLogoUrl           String?\n\n  updatedAt DateTime @updatedAt\n}\n\n// ------------------------------------------------------------------------------\n// SHOPPING CART & CART ITEMS\n// ------------------------------------------------------------------------------\n\nmodel Cart {\n  id        String     @id @default(cuid())\n  userId    String?    @unique\n  user      User?      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  sessionId String?    @unique // Anonymous guest cart token / session identifier\n  items     CartItem[]\n  createdAt DateTime   @default(now())\n  updatedAt DateTime   @updatedAt\n\n  @@index([userId])\n  @@index([sessionId])\n}\n\nmodel CartItem {\n  id        String          @id @default(cuid())\n  cartId    String\n  cart      Cart            @relation(fields: [cartId], references: [id], onDelete: Cascade)\n  productId String\n  product   Product         @relation(fields: [productId], references: [id], onDelete: Restrict)\n  variantId String?\n  variant   ProductVariant? @relation(fields: [variantId], references: [id], onDelete: SetNull)\n  quantity  Int             @default(1)\n  createdAt DateTime        @default(now())\n  updatedAt DateTime        @updatedAt\n\n  @@index([cartId])\n  @@index([productId])\n  @@index([variantId])\n}\n\n// ------------------------------------------------------------------------------\n// BACK-IN-STOCK ALERTS (Phase 15.4)\n// ------------------------------------------------------------------------------\n\nmodel BackInStockAlert {\n  id                  String                 @id @default(cuid())\n  userId              String\n  user                User                   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  productId           String\n  product             Product                @relation(fields: [productId], references: [id], onDelete: Cascade)\n  status              BackInStockAlertStatus @default(PENDING)\n  failureReason       String?\n  sentAt              DateTime?\n  processingStartedAt DateTime?\n  leaseExpiresAt      DateTime?\n  deliveryAttempts    Int                    @default(0)\n  lastAttemptAt       DateTime?\n  idempotencyKey      String?\n  uncertainDelivery   Boolean                @default(false)\n  createdAt           DateTime               @default(now())\n  updatedAt           DateTime               @updatedAt\n\n  @@index([userId])\n  @@index([productId])\n  @@index([status])\n  @@index([productId, status])\n  @@index([status, leaseExpiresAt])\n}\n\n// ------------------------------------------------------------------------------\n// NEWSLETTER & CONSENT MANAGEMENT (Phase 15.6)\n// ------------------------------------------------------------------------------\n\nenum NewsletterSubscriberStatus {\n  PENDING\n  VERIFIED\n  UNSUBSCRIBED\n}\n\nenum NewsletterConsentEventType {\n  CONSENT_GIVEN\n  EMAIL_VERIFIED\n  UNSUBSCRIBED\n  RESUBSCRIPTION_REQUESTED\n}\n\nmodel NewsletterSubscriber {\n  id                 String                     @id @default(cuid())\n  email              String                     @unique\n  status             NewsletterSubscriberStatus @default(PENDING)\n  consentGivenAt     DateTime                   @default(now())\n  consentSource      String                     @default(\"WEBSITE_FOOTER\")\n  consentTextVersion String                     @default(\"v1.0\")\n  unsubscribeToken   String                     @unique @default(cuid())\n  verifiedAt         DateTime?\n  unsubscribedAt     DateTime?\n  createdAt          DateTime                   @default(now())\n  updatedAt          DateTime                   @updatedAt\n\n  verificationTokens NewsletterVerificationToken[]\n  consentEvents      NewsletterConsentEvent[]\n\n  @@index([status])\n  @@index([createdAt])\n  @@map(\"newsletter_subscribers\")\n}\n\nmodel NewsletterVerificationToken {\n  id           String    @id @default(cuid())\n  subscriberId String\n  tokenHash    String    @unique\n  expiresAt    DateTime\n  usedAt       DateTime?\n  createdAt    DateTime  @default(now())\n\n  subscriber NewsletterSubscriber @relation(fields: [subscriberId], references: [id], onDelete: Cascade)\n\n  @@index([subscriberId])\n  @@index([expiresAt])\n  @@map(\"newsletter_verification_tokens\")\n}\n\nmodel NewsletterConsentEvent {\n  id                 String                     @id @default(cuid())\n  subscriberId       String\n  eventType          NewsletterConsentEventType\n  consentTextVersion String                     @default(\"v1.0\")\n  consentSource      String                     @default(\"WEBSITE_FOOTER\")\n  metadata           Json?\n  createdAt          DateTime                   @default(now())\n\n  subscriber NewsletterSubscriber @relation(fields: [subscriberId], references: [id], onDelete: Cascade)\n\n  @@index([subscriberId])\n  @@index([eventType])\n  @@index([createdAt])\n  @@map(\"newsletter_consent_events\")\n}\n\n// ------------------------------------------------------------------------------\n// ADMINISTRATOR INVITATIONS (Phase 2)\n// ------------------------------------------------------------------------------\n\nmodel AdminInvitation {\n  id           String    @id @default(cuid())\n  email        String\n  tokenHash    String    @unique\n  name         String\n  phone        String?\n  role         UserRole  @default(STAFF)\n  roleId       String?\n  roleRelation Role?     @relation(fields: [roleId], references: [id], onDelete: Restrict)\n  expiresAt    DateTime\n  usedAt       DateTime?\n  invitedById  String\n  invitedBy    User      @relation(\"InvitedAdmins\", fields: [invitedById], references: [id], onDelete: Cascade)\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  @@index([email])\n  @@index([tokenHash])\n  @@index([invitedById])\n  @@index([roleId])\n  @@map(\"admin_invitations\")\n}\n\n// ------------------------------------------------------------------------------\n// ROLES & GRANULAR PERMISSIONS (Phase 3)\n// ------------------------------------------------------------------------------\n\nmodel Role {\n  id          String   @id @default(cuid())\n  name        String   @unique\n  slug        String   @unique\n  description String?\n  isSystem    Boolean  @default(false)\n  isActive    Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  users       User[]\n  permissions RolePermission[]\n  invitations AdminInvitation[]\n\n  @@index([slug])\n  @@index([isActive])\n  @@map(\"roles\")\n}\n\nmodel Permission {\n  id          String   @id @default(cuid())\n  key         String   @unique\n  displayName String\n  description String?\n  category    String\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  roles RolePermission[]\n\n  @@index([category])\n  @@map(\"permissions\")\n}\n\nmodel RolePermission {\n  roleId       String\n  permissionId String\n  assignedAt   DateTime @default(now())\n\n  role       Role       @relation(fields: [roleId], references: [id], onDelete: Cascade)\n  permission Permission @relation(fields: [permissionId], references: [id], onDelete: Cascade)\n\n  @@id([roleId, permissionId])\n  @@map(\"role_permissions\")\n}\n\nenum SkuOwnerType {\n  PRODUCT\n  VARIANT\n}\n\nmodel GlobalSku {\n  sku       String          @id\n  ownerType SkuOwnerType\n  productId String?         @unique\n  product   Product?        @relation(fields: [productId], references: [id], onDelete: Cascade)\n  variantId String?         @unique\n  variant   ProductVariant? @relation(fields: [variantId], references: [id], onDelete: Cascade)\n  createdAt DateTime        @default(now())\n\n  @@index([productId])\n  @@index([variantId])\n}\n\nmodel SkuSequence {\n  prefix       String   @id\n  lastSequence Int      @default(0)\n  updatedAt    DateTime @updatedAt\n}\n\n// ------------------------------------------------------------------------------\n// PRODUCT BULK IMPORT EXECUTION (Phase 4 – Stage 4)\n// ------------------------------------------------------------------------------\n\nenum ImportStockMode {\n  SET_STOCK\n  ADD_STOCK\n}\n\nenum ImportBatchStatus {\n  PENDING\n  PROCESSING\n  COMPLETED\n  PARTIALLY_FAILED\n  FAILED\n}\n\nenum ImportRowStatus {\n  SUCCESS\n  FAILED\n  SKIPPED\n}\n\nmodel ProductImportPreview {\n  id              String   @id @default(cuid())\n  fileName        String\n  fileSize        Int\n  fileSha256      String\n  previewChecksum String\n  normalizedRows  Json\n  summary         Json\n  createdById     String\n  createdBy       User     @relation(\"ImportPreviewsCreated\", fields: [createdById], references: [id])\n  expiresAt       DateTime\n  createdAt       DateTime @default(now())\n\n  batches ProductImportBatch[]\n\n  @@index([createdById])\n  @@index([expiresAt])\n}\n\nmodel ImportExecutionLease {\n  id           String   @id @default(\"GLOBAL_IMPORT_LEASE\")\n  batchId      String?\n  ownerId      String?\n  status       String   @default(\"IDLE\") // IDLE, ACTIVE\n  currentChunk Int      @default(0)\n  heartbeatAt  DateTime @default(now())\n  expiresAt    DateTime @default(now())\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n}\n\nmodel ProductImportBatch {\n  id                 String            @id @default(cuid())\n  idempotencyKey     String            @unique\n  adminId            String\n  previewId          String\n  requestFingerprint String\n  stockMode          ImportStockMode   @default(SET_STOCK)\n  allowUpdates       Boolean           @default(true)\n  status             ImportBatchStatus @default(PENDING)\n  totalRows          Int               @default(0)\n  totalChunks        Int               @default(0)\n  committedChunk     Int               @default(0)\n  processedRows      Int               @default(0)\n  successfulRows     Int               @default(0)\n  failedRows         Int               @default(0)\n  startedAt          DateTime?\n  completedAt        DateTime?\n  createdAt          DateTime          @default(now())\n  updatedAt          DateTime          @updatedAt\n\n  admin   User                     @relation(\"ImportBatchesCreated\", fields: [adminId], references: [id])\n  preview ProductImportPreview     @relation(fields: [previewId], references: [id])\n  results ProductImportRowResult[]\n\n  @@index([adminId])\n  @@index([status])\n  @@index([createdAt])\n}\n\nmodel ProductImportRowResult {\n  id           String          @id @default(cuid())\n  batchId      String\n  rowNumber    Int\n  sku          String?\n  action       String\n  status       ImportRowStatus\n  productId    String?\n  variantId    String?\n  errorCode    String?\n  errorMessage String?\n  createdAt    DateTime        @default(now())\n\n  batch ProductImportBatch @relation(fields: [batchId], references: [id], onDelete: Cascade)\n\n  @@index([batchId, rowNumber])\n  @@index([batchId, status])\n}\n\n// ------------------------------------------------------------------------------\n// PHASE 2: SECURITY STEP-UP DOUBLE VERIFICATION & ADMINISTRATIVE AUDIT\n// ------------------------------------------------------------------------------\n\nenum VerificationChallengeStatus {\n  PENDING\n  VERIFIED\n  CONSUMED\n  EXPIRED\n  FAILED\n}\n\nmodel VerificationChallenge {\n  id           String                      @id @default(cuid())\n  userId       String\n  action       String\n  codeHash     String\n  resourceType String?\n  resourceId   String?\n  metadata     Json?\n  attempts     Int                         @default(0)\n  maxAttempts  Int                         @default(3)\n  status       VerificationChallengeStatus @default(PENDING)\n  expiresAt    DateTime\n  verifiedAt   DateTime?\n  consumedAt   DateTime?\n  createdAt    DateTime                    @default(now())\n  updatedAt    DateTime                    @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId, status])\n  @@index([expiresAt])\n}\n\nmodel AdminActivityLog {\n  id          String   @id @default(cuid())\n  userId      String?\n  userEmail   String?\n  userName    String?\n  userRole    String?\n  action      String\n  entityType  String\n  entityId    String?\n  description String\n  status      String   @default(\"SUCCESS\")\n  ipAddress   String?\n  userAgent   String?\n  beforeState Json?\n  afterState  Json?\n  challengeId String?\n  createdAt   DateTime @default(now())\n\n  user User? @relation(fields: [userId], references: [id], onDelete: SetNull)\n\n  @@index([userId])\n  @@index([action])\n  @@index([entityType, entityId])\n  @@index([createdAt])\n  @@index([status])\n}\n"
}

